                                                                                                                                                                                                                                                                                                               
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TENANT_AREA_UPGRADE_USERS_V" ("FAB_ID", "FAB_NAME", "TENANT_ID", "ORG_GROUP_CODE", "USER_CODE", "USER_GROUP_CODE", "EXT_ORG_ID", "EXT_ORG_NAME", "UPGRADE_LEVEL", "EXT_USER_ID", "NAME", "JOB_NUMBER", "MOBILE", "SYNC_USER_ID", "BASE_DEPT_ID") AS     
  select f.FAB_ID,                                                                                                                                                                                                                                                                                             
       f.NAME                              as FAB_NAME,                                                                                                                                                                                                                                                        
       f.TENANT_ID,                                                                                                                                                                                                                                                                                            
       ga.ORG_GROUP_CODE,                                                                                                                                                                                                                                                                                      
       ga.USER_GROUP_ASSO_CODE             as USER_CODE,                                                                                                                                                                                                                                                       
       ug.CODE                             as USER_GROUP_CODE,                                                                                                                                                                                                                                                 
       ga.BIND_EXT_ORG_ID                  as EXT_ORG_ID,                                                                                                                                                                                                                                                      
       SELECT_ORG_NAME(ga.BIND_EXT_ORG_ID) as EXT_ORG_NAME,                                                                                                                                                                                                                                                    
       (                                                                                                                                                                                                                                                                                                       
           CASE                                                                                                                                                                                                                                                                                                
               when ug.CODE = 'PRODUCTION_GRID_SERVICE_CENTER' then -1                                                                                                                                                                                                                                         
               when ga.USER_GROUP_ASSO_CODE = 'DEPARTMENT_ASSISTANT_MANAGER' then 1                                                                                                                                                                                                                            
               when ga.USER_GROUP_ASSO_CODE = 'DEPARTMENT_MANAGER' then 2                                                                                                                                                                                                                                      
               when ug.CODE = 'DECISION_CENTER' and ga.USER_GROUP_ASSO_CODE != 'GENERAL_MANAGER' then 3                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                               
               when ug.CODE = 'DECISION_CENTER' and ga.USER_GROUP_ASSO_CODE = 'GENERAL_MANAGER' then 4                                                                                                                                                                                                         
               else -2                                                                                                                                                                                                                                                                                         
               END                                                                                                                                                                                                                                                                                             
           )                               as UPGRADE_LEVEL,                                                                                                                                                                                                                                                   
       ga.EXT_USER_ID,                                                                                                                                                                                                                                                                                         
       u.NAME,                                                                                                                                                                                                                                                                                                 
       u.JOB_NUMBER,                                                                                                                                                                                                                                                                                           
       u.MOBILE,                                                                                                                                                                                                                                                                                               
       u.SYNC_USER_ID,                                                                                                                                                                                                                                                                                         
       f.BASE_DEPT_ID                                                                                                                                                                                                                                                                                          
from FND_FAB f                                                                                                                                                                                                                                                                                                 
         inner join TENANT_USER_GROUP ug on ug.FAB_ID = f.FAB_ID                                                                                                                                                                                                                                               
         inner join TENANT_USER_GROUP_ASSO ga on ug.USER_GROUP_ID = ga.USER_GROUP_ID                                                                                                                                                                                                                           
         inner join MPF_SHARE_USER_V u on ga.EXT_USER_ID = u.EXT_USER_ID and u.IS_LEAVE = 0                                                                                                                                                                                                                    
order by f.FAB_ID, ga.ORG_GROUP_CODE, USER_GROUP_CODE;                                                                                                                                                                                                                                                         

